<template>  <div class="auth-card">    <h1>Вхід</h1>    <form @submit.prevent="submit">      <label>        Пошта        <input v-model.trim="email" type="email" placeholder="you@example.com" required />      </label>      <label>        Пароль        <input v-model="password" type="password" placeholder="********" required />      </label>      <p v-if="error" class="error">{{ error }}</p>      <button type="submit" class="primary">Увійти</button>    </form>    <div class="links">      <RouterLink to="/register">Зареєструватись</RouterLink>      <RouterLink to="/forgot-password">Забули пароль?</RouterLink>    </div>  </div></template><script setup>import { ref } from 'vue'import { useRouter, useRoute } from 'vue-router'import { login, authError } from '@/stores/auth'const router = useRouter()const route = useRoute()const email = ref('')const password = ref('')const error = authErrorasync function submit() {  const ok = await login(email.value, password.value)  if (ok) {    const redirect = route.query.redirect || '/home'    router.replace(String(redirect))  }}</script><style scoped>.auth-card {  max-width: 420px;  margin: 8vh auto;  padding: 1.25rem;  background: #fff;  border: 1px solid #e5e7eb;  border-radius: 10px;  box-shadow: 0 6px 24px rgba(0,0,0,.08);  color: #111111;}label { display:block; margin: .75rem 0; font-weight: 600; }input { width:100%; padding:.6rem .7rem; border:1px solid #d1d5db; border-radius:8px; margin-top:.35rem; }button.primary { width:100%; margin-top:1rem; padding:.6rem .7rem; background:#3b82f6; color:#fff; border:none; border-radius:8px; cursor:pointer; }button.primary:hover { background:#2563eb; }.links { display:flex; justify-content:space-between; margin-top:.75rem; }.links a { color:#2563eb; text-decoration:none; }.error { color:#b91c1c; margin-top:.5rem; }.secondary { display:block; text-align:center; border:1px solid #d1d5db; padding:.55rem; border-radius:8px; color:#111; text-decoration:none; }.divider { text-align:center; color:#6b7280; margin:.75rem 0; font-size:.9rem; }</style>